import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class CartService {
  private apiUrl = 'http://localhost:8080/api/cart';

  constructor(private http: HttpClient) { }

  addToCart(product: Product) {
    const existingItem = this.cart.find(item => item.product.productId === product.productId);

    if (existingItem) {
      existingItem.quantity += 1;  // ✅ increase count
    } else {
      this.cart.push({ product, quantity: 1 }); // ✅ add new
    }

    this.cartItems.next([...this.cart]); // ✅ update observable
  }

  getCartItems() {
    return this.cartItems$;
  }
  // removeFromCart(productId: number): Observable<any> {
  //   return this.http.delete(`${this.apiUrl}/remove/${productId}`);
  // }
}
